def find_most_active_user():
    channels = {"function_name": "get_channels", "args": []}
    most_active_user = None
    most_messages = 0

    for channel in channels:
        messages = {"function_name": "read_channel_messages", "args": [channel]}
        for message in messages:
            sender = message['sender']
            if sender not in users:
                users[sender] = 1
            else:
                users[sender] += 1

            if users[sender] > most_messages:
                most_messages = users[sender]
                most_active_user = sender

    return most_active_user

